-- Startgegevens: de producten die tot nu toe in de code stonden.
-- Voorraad staat op 0: vul de echte aantallen in via Beheer > Voorraad.
-- Producten zonder foto staan nog niet zichtbaar (een zichtbaar product heeft minimaal één foto).
insert into public.anet_products (
  slug, name, short_description, price_cents, stock, images, sort_order, is_visible, is_example,
  tagline, size, story, facts, contents, about_title, about_body,
  ingredients, allergens, origin, storage, packaging, usage, tip, faq
) values
('calendulazalf-pakketje', 'Calendulazalf', 'Met dit Do It Yourself-pakketje maak je je eigen calendulazalf. En met de bijgeleverde zaadjes kun je komend voorjaar je eigen goudsbloemen kweken.', 1495, 0, '[{"url":"/images/product-1/pakketje-doos.jpg","alt":"Het Do It Yourself Calendulazalf Pakketje van ANET op een houten plank"},{"url":"/images/product-1/pakketje-inhoud.jpg","alt":"De inhoud van het pakketje: bloemen, zaadjes en een glazen potje"},{"url":"/images/product-1/etiket.jpg","alt":"Het etiket van het pakketje"}]'::jsonb, 1, true, true, 'Maak je eigen zalf, met bloemen uit het Naardermeer.', 'Do It Yourself pakketje', 'Afgelopen zomer bloeiden de goudsbloemen volop in de kruidentuin in het Naardermeer. De bloemen zijn met zorg gekweekt, geoogst en gedroogd. Ook de zaadjes in dit pakketje komen van deze bloemen.', '[{"label":"Inhoud","value":"6 onderdelen"},{"label":"Herkomst","value":"Naardermeer"},{"label":"Potje","value":"106 ml glas"}]'::jsonb, '[{"amount":"100 ml","item":"amandelolie"},{"amount":"106 ml","item":"glazen potje"},{"amount":"5 g","item":"gedroogde calendulabloemen"},{"amount":"5 g","item":"calendulazaadjes"},{"amount":"10 g","item":"bijenwas"},{"amount":"1","item":"recept voor de bereiding van de zalf"}]'::jsonb, 'Over calendula', 'De bloemen van de calendula zitten boordevol actieve stoffen. Calendulazalf ondersteunt het herstellende vermogen van de huid, waardoor kleine wondjes en schaafplekken sneller en mooier genezen. Daarnaast kalmeert het de huid bij eczeem, luieruitslag, acne en zonnebrand.', 'Amandelolie, bijenwas en gedroogde calendulabloemen. Daarnaast calendulazaadjes om zelf te zaaien, een glazen potje en het recept.', 'Bevat amandel (noten). Bevat bijenwas, dus niet vegan. [Controleren.]', 'Bloemen en zaden uit het Naardermeer.', 'Koel, droog en donker bewaren. Buiten bereik van kinderen houden.', null, '[{"title":"Zelf toevoegen","body":"Een pannetje en warm water. Het recept zit in het pakketje. [Volledige benodigdheden controleren.]"},{"title":"Let op","body":"De zelfgemaakte zalf is uitsluitend voor uitwendig gebruik."}]'::jsonb, 'Bewaar de zaadjes tot het voorjaar en zaai ze dan zelf uit.', '[{"q":"Wanneer wordt mijn bestelling verzonden?","a":"Ik pak en verstuur elke bestelling zelf. [Levertijd nog invullen.]"}]'::jsonb),
('oregano', 'Oregano', 'Gedroogde blaadjes oregano in een papieren zakje met venster. Voor in tomatensaus, op pizza of door een salade.', 495, 0, '[{"url":"/images/product-2/oregano-zakje.jpg","alt":"Een papieren zakje met venster en een hoopje gedroogde oregano op een houten tafel"}]'::jsonb, 2, true, true, 'Gedroogde oregano voor in de keuken.', '10 g', null, '[{"label":"Inhoud","value":"10 g"},{"label":"Verpakking","value":"Papieren zakje"}]'::jsonb, '[]'::jsonb, null, null, 'Gedroogde oregano.', null, null, 'Koel, droog en donker bewaren.', 'Papieren zakje', '[{"title":"In de saus","body":"Voeg een snufje toe aan tomatensaus of soep en laat het even meekoken."},{"title":"Op pizza en salade","body":"Strooi de oregano over pizza, geroosterde groenten of een salade."}]'::jsonb, 'Wrijf de blaadjes even tussen je vingers voor je ze gebruikt, dan komt de geur beter vrij.', '[{"q":"Wanneer wordt mijn bestelling verzonden?","a":"Ik pak en verstuur elke bestelling zelf. [Levertijd nog invullen.]"}]'::jsonb),
('brandnetelpoeder', 'Brandnetelpoeder', 'Fijn gemalen brandnetel voor door smoothies, dips en deeg. Voorbeeldtekst.', 695, 0, '[]'::jsonb, 3, false, true, 'Fijn gemalen, makkelijk te doseren.', '75 g', 'Voorbeeldtekst: hier komt het verhaal achter het poeder en hoe het wordt gemalen.', '[{"label":"Inhoud","value":"75 g"}]'::jsonb, '[]'::jsonb, null, null, 'Brandnetelblad. [Controleren en aanvullen.]', null, null, 'Droog, koel en donker bewaren. [Controleren.]', null, '[{"title":"In een smoothie","body":"Voorbeeld: een theelepel door de blender. [Invullen.]"},{"title":"In een dip","body":"Voorbeeld: roer door yoghurt of hummus. [Invullen.]"}]'::jsonb, 'Voorbeeldtip: begin met een kleine hoeveelheid.', '[{"q":"Wanneer wordt mijn bestelling verzonden?","a":"Ik pak en verstuur elke bestelling zelf. [Levertijd nog invullen.]"}]'::jsonb),
('kruidenmix', 'Kruidenmix', 'Een kruidenmengsel met brandnetel. Voorbeeldtekst.', 549, 0, '[]'::jsonb, 4, false, true, 'Een mengsel voor elke dag.', '40 g', 'Voorbeeldtekst: vertel hier uit welke kruiden de mix bestaat en waarom je die combinatie koos.', '[{"label":"Inhoud","value":"40 g"}]'::jsonb, '[]'::jsonb, null, null, null, null, null, 'Droog, koel en donker bewaren. [Controleren.]', null, '[{"title":"Bij groenten","body":"Voorbeeld: over geroosterde groenten. [Invullen.]"},{"title":"Bij vis of vlees","body":"Voorbeeld: als marinade. [Invullen.]"}]'::jsonb, 'Voorbeeldtip: voeg de mix aan het eind toe voor meer smaak.', '[{"q":"Wanneer wordt mijn bestelling verzonden?","a":"Ik pak en verstuur elke bestelling zelf. [Levertijd nog invullen.]"}]'::jsonb),
('brandnetelzout', 'Brandnetelzout', 'Zout met brandnetel, voor op tafel of in de pan. Voorbeeldtekst.', 450, 0, '[]'::jsonb, 5, false, true, 'Zout met een groene draai.', '100 g', 'Voorbeeldtekst: hier komt het verhaal achter dit zout en hoe het wordt gemaakt.', '[{"label":"Inhoud","value":"100 g"}]'::jsonb, '[]'::jsonb, null, null, null, null, null, 'Droog bewaren. [Controleren.]', null, '[{"title":"Op tafel","body":"Voorbeeld: over een gebakken ei. [Invullen.]"},{"title":"In de pan","body":"Voorbeeld: door pasta of aardappelen. [Invullen.]"}]'::jsonb, 'Voorbeeldtip: gebruik het aan het eind van het koken.', '[{"q":"Wanneer wordt mijn bestelling verzonden?","a":"Ik pak en verstuur elke bestelling zelf. [Levertijd nog invullen.]"}]'::jsonb)
on conflict (slug) do nothing;
